{
  "status": "invalid",
  "mode": "archival",
  "profile": "jep-core-0.7",
  "event_identity": {
    "who": "did:example:agent-789",
    "id": "urn:uuid:018f4f8d-7c63-7c2e-9b43-4ef657eec1c0"
  },
  "event_hash": null,
  "checks": {
    "syntax": "pass",
    "cryptographic": "fail",
    "event_identity": "not_checked",
    "reference_integrity": "not_checked",
    "extension_processing": "not_checked"
  },
  "warnings": [],
  "errors": [
    {
      "code": "ERR_SIGNATURE_INVALID",
      "check": "cryptographic",
      "message": "The signature does not verify over the JEP Signing Payload."
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://jep.org/schemas/jep-event-0.7.schema.json",
  "title": "JEP-Core 0.7 Event",
  "type": "object",
  "required": [
    "jep",
    "id",
    "verb",
    "who",
    "when",
    "what",
    "sig"
  ],
  "properties": {
    "jep": {
      "type": "string",
      "const": "1"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "description": "Non-empty ASCII Event ID; semantic validation is performed by the Core validator."
    },
    "verb": {
      "type": "string",
      "enum": [
        "J",
        "D",
        "T",
        "V"
      ]
    },
    "who": {
      "type": "string",
      "minLength": 1
    },
    "when": {
      "type": "integer"
    },
    "what": {},
    "aud": {},
    "ref": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "object"
        }
      ]
    },
    "ext": {
      "type": "object"
    },
    "ext_crit": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "uniqueItems": true
    },
    "sig": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "object"
        }
      ]
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "verb": {
            "const": "D"
          }
        }
      },
      "then": {
        "properties": {
          "what": {
            "type": "object",
            "required": [
              "delegatee",
              "scope"
            ]
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "verb": {
            "const": "T"
          }
        }
      },
      "then": {
        "required": [
          "ref"
        ],
        "properties": {
          "what": {
            "type": "object",
            "required": [
              "termination_scope"
            ]
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "verb": {
            "const": "V"
          }
        }
      },
      "then": {
        "required": [
          "ref"
        ],
        "properties": {
          "what": {
            "type": "object",
            "required": [
              "verification_scope",
              "result"
            ]
          }
        }
      }
    }
  ]
}
